INSERT INTO `coupons` (`id`, `code`, `description`, `type`, `value`, `min_subtotal`, `usage_limit`, `used_count`, `starts_at`, `ends_at`, `is_active`, `created_at`, `updated_at`) VALUES (3, 'FREESHIP', 'Complimentary shipping', 'free_shipping', 0, 0, NULL, 0, NULL, NULL, 1, '2026-09-16 05:53:00', '2026-09-16 05:53:00');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (1, 'Orders', 'How do I place an order?', 'Add pieces to your bag, proceed to checkout and follow the steps for contact details, delivery address and payment. You will receive a confirmation email with your order number immediately.', 0, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (2, 'Orders', 'Can I change or cancel my order?', 'Orders can be changed or cancelled within two hours of being placed. Contact client care with your order number and we will do our best to help before the order is dispatched.', 1, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (3, 'Orders', 'Where is my order confirmation?', 'Confirmations are sent within minutes to the email used at checkout. Please check your spam folder; if it is still missing, contact client care.', 2, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (4, 'Shipping', 'How long does delivery take?', 'Standard delivery takes 3–5 business days across India. Express delivery arrives in 1–2 business days in metro cities. International delivery takes 5–10 business days.', 3, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (5, 'Shipping', 'Do you offer free shipping?', 'Yes — standard delivery is complimentary on orders over ₹15,000 and express delivery is complimentary over ₹40,000.', 4, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (6, 'Shipping', 'Do you ship internationally?', 'We ship to over 40 countries. Duties and taxes are calculated at checkout so there are no surprises on delivery.', 5, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (7, 'Returns', 'What is your return policy?', 'You have 30 days from delivery to return any unworn piece with its tags attached for a full refund. Returns are collected from your door at no charge.', 6, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (8, 'Returns', 'How do I start a return?', 'Sign in to your account, open the order and choose “Start a return”, or contact client care with your order number. We will arrange collection within 48 hours.', 7, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (9, 'Exchanges', 'Can I exchange for a different size?', 'Yes. Request an exchange within 30 days and we will send the new size as soon as the original is collected — usually within 2–3 business days.', 8, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (10, 'Exchanges', 'Can I exchange a gift?', 'Gifts can be exchanged for another size or colour, or for store credit, within 30 days of the original delivery date.', 9, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (11, 'Payments', 'Which payment methods do you accept?', 'Visa, Mastercard, American Express, RuPay, UPI, net banking, major wallets and cash on delivery (a small handling fee applies to COD).', 10, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (12, 'Payments', 'Is my payment information secure?', 'All payments are processed over 256-bit encrypted connections by PCI-DSS compliant partners. We never store your card details.', 11, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (13, 'Products', 'How do I find my size?', 'Every product page links to our size guide with detailed measurements. If you are between sizes, we suggest sizing up for outerwear and down for knitwear.', 12, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (14, 'Products', 'Are your products authentic?', 'Every piece is designed by the house and made in our partner ateliers. Each order ships with a certificate of authenticity.', 13, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (15, 'Account', 'Do I need an account to order?', 'No — you can check out as a guest. An account lets you track orders, save addresses and keep a wishlist across devices.', 14, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (16, 'Account', 'How do I reset my password?', 'Use “Forgot password” on the sign-in page and we will email you a secure reset link.', 15, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (17, 'General', 'Do you have physical boutiques?', 'Yes. Our flagship is in Bengaluru with boutiques in Mumbai and New Delhi. See the store locator for hours and directions.', 16, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (18, 'General', 'How can I contact you?', 'Email care@maisonelan.com or call +91 80 4500 1200, Monday to Saturday, 10:00–19:00 IST.', 17, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01');
