INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`) VALUES (3, 'The Signature Collection', 'the-signature-collection', 'Campaign', 'Behind the lens of our Autumn campaign — shot over three days in a converted textile mill.', '<p>Behind the lens of our Autumn campaign — shot over three days in a converted textile mill.</p><p>Full story coming soon.</p>', 'https://images.unsplash.com/photo-1524504388940-b1c1722653e1?w=1200&q=80&auto=format&fit=crop&h=1500', '8 min read', '2026-08-12 10:00:00', 0, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 04:51:11');
